<?php
namespace App\Imports;
use App\Models\Product; use Illuminate\Support\Collection; use Maatwebsite\Excel\Concerns\ToCollection; use Maatwebsite\Excel\Concerns\WithStartRow;
class DailyReportProductMasterImport implements ToCollection, WithStartRow { public function startRow():int{return 2;} public function collection(Collection $rows):void{foreach($rows as $row){$mm=$this->number($row[1]??null);$description=trim((string)($row[2]??''));$qty=(int)($row[3]??0);if($mm===null||$description===''||$qty<1)continue;$product=Product::withTrashed()->where('mm_number',$mm)->first()??Product::withTrashed()->where('name',$description)->first()??new Product();$product->fill(['code'=>$product->code??'MM-'.$mm,'name'=>$product->name??$description,'mm_number'=>$mm,'description'=>$description,'qty_per_box'=>$qty,'is_active'=>true]);$product->save();if($product->trashed())$product->restore();}} private function number(mixed $value):?string{if($value===null||$value==='')return null;return preg_replace('/\.0+$/','',(string)$value);} }
